.super-search-widget {
  --super-search-surface: #ffffff;
  --super-search-surface-soft: #ffffff;
  --super-search-border: #c7cfca;
  --super-search-text: #191b21;
  --super-search-muted: #5b676d;
  --super-search-accent: #083c5e;
  --super-search-accent-soft: #dbe7ee;
  --super-search-button: #302826;
  --super-search-button-hover: #231d1b;
  --super-search-shadow: 0 12px 28px rgba(25, 27, 33, 0.08);
  background: var(--super-search-surface);
  border: 1px solid var(--super-search-border);
  border-radius: 14px;
  box-shadow: var(--super-search-shadow);
  font-family: "Roboto", "Segoe UI", Arial, sans-serif;
  padding: 32px 28px 28px;
  position: relative;
}

.super-search-widget::before {
  background: linear-gradient(90deg, var(--super-search-accent) 0%, #5783a6 100%);
  border-radius: 999px;
  content: "";
  height: 4px;
  left: 28px;
  position: absolute;
  top: 18px;
  width: 72px;
}

.super-search-widget--compact {
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
}

.super-search-widget--compact::before {
  content: none;
}

.super-search-widget__form {
  margin: 0;
}

.super-search-widget__top-row {
  align-items: center;
  display: flex;
  gap: 18px;
  justify-content: space-between;
  margin-bottom: 18px;
}

.super-search-widget__greeting {
  color: var(--super-search-text);
  flex: 1 1 auto;
  font-size: 21px;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.25;
  margin: 0;
  max-width: 28ch;
}

.super-search-widget__filter-wrap {
  align-items: center;
  display: flex;
  flex: 0 0 auto;
  gap: 10px;
}

.super-search-widget__filter-label {
  color: var(--super-search-muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  margin: 0;
  text-transform: uppercase;
}

.super-search-widget__filter-select {
  appearance: none;
  background-color: #ffffff;
  background-image:
    linear-gradient(45deg, transparent 50%, #52636b 50%),
    linear-gradient(135deg, #52636b 50%, transparent 50%);
  background-position:
    calc(100% - 16px) calc(50% - 3px),
    calc(100% - 10px) calc(50% - 3px);
  background-repeat: no-repeat;
  background-size: 6px 6px, 6px 6px;
  border: 1px solid var(--super-search-border);
  border-radius: 10px;
  box-shadow: none;
  color: var(--super-search-text);
  font-size: 14px;
  font-weight: 600;
  height: 40px;
  min-width: 190px;
  padding: 0 32px 0 12px;
}

.super-search-widget__filter-select:focus {
  border-color: var(--super-search-accent);
  box-shadow: 0 0 0 3px rgba(8, 60, 94, 0.12);
}

.super-search-widget__surface {
  background: transparent;
  border: 0;
  border-radius: 0;
  padding: 0;
}

.super-search-widget__controls {
  display: flex;
  width: 100%;
}

.super-search-widget__input-wrap {
  align-items: center;
  background: var(--super-search-surface-soft);
  border: 1px solid var(--super-search-border);
  border-radius: 16px;
  box-shadow: 0 6px 18px rgba(25, 27, 33, 0.06);
  display: flex;
  flex: 1 1 auto;
  min-height: 68px;
  padding: 7px 7px 7px 22px;
  position: relative;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}

.super-search-widget__input-wrap:focus-within {
  background: #ffffff;
  border-color: var(--super-search-accent);
  box-shadow: 0 0 0 3px rgba(8, 60, 94, 0.12), 0 10px 24px rgba(25, 27, 33, 0.08);
}

.super-search-widget__input {
  background: transparent;
  border: 0;
  box-shadow: none;
  color: var(--super-search-text);
  flex: 1 1 auto;
  font-size: 17px;
  font-weight: 400;
  height: 48px;
  padding: 0;
  padding-right: 82px;
  position: relative;
  z-index: 1;
}

.super-search-widget__input.form-control:focus {
  border: 0;
  box-shadow: none;
}

.super-search-widget__input::placeholder {
  color: #707d84;
  opacity: 1;
}

.super-search-widget__button {
  align-items: center;
  background: radial-gradient(circle at 35% 35%, #3b332f 0%, var(--super-search-button) 70%);
  border: 0;
  border-radius: 999px;
  box-shadow: 0 14px 28px rgba(33, 27, 25, 0.28);
  color: #ffffff;
  display: inline-flex;
  height: 50px;
  justify-content: center;
  min-width: 50px;
  padding: 0;
  position: absolute;
  right: 7px;
  top: 50%;
  transform: translateY(-50%);
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
  width: 50px;
  z-index: 1;
}

.super-search-widget__button svg {
  display: block;
  fill: currentColor;
  height: 22px;
  width: 22px;
}

.super-search-widget__button-text {
  border: 0;
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
}

.super-search-widget__button:hover,
.super-search-widget__button:focus,
.super-search-widget__button:active {
  background: radial-gradient(circle at 35% 35%, #332c28 0%, var(--super-search-button-hover) 70%);
  box-shadow: 0 18px 34px rgba(33, 27, 25, 0.34);
  transform: translateY(-50%) scale(1.02);
}

.super-search-widget--compact .super-search-widget__input-wrap {
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(25, 27, 33, 0.05);
  min-height: 48px;
  padding: 4px 4px 4px 15px;
}

.super-search-widget--compact .super-search-widget__input {
  font-size: 16px;
  height: 38px;
  padding-right: 64px;
}

.super-search-widget--compact .super-search-widget__button {
  box-shadow: 0 10px 20px rgba(33, 27, 25, 0.22);
  height: 38px;
  min-width: 38px;
  right: 4px;
  width: 38px;
}

.super-search-widget--compact .super-search-widget__button svg {
  height: 18px;
  width: 18px;
}

@media (max-width: 767px) {
  .super-search-widget {
    border-radius: 12px;
    padding: 28px 20px 20px;
  }

  .super-search-widget::before {
    left: 20px;
    top: 14px;
    width: 56px;
  }

  .super-search-widget__greeting {
    font-size: 19px;
  }

  .super-search-widget__top-row {
    align-items: stretch;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 12px;
  }

  .super-search-widget__filter-wrap {
    justify-content: space-between;
    width: 100%;
  }

  .super-search-widget__filter-select {
    min-width: 0;
    width: 100%;
  }

  .super-search-widget__input-wrap,
  .super-search-widget__button {
    min-height: 52px;
  }

  .super-search-widget__input-wrap {
    min-height: 58px;
    padding-left: 18px;
  }

  .super-search-widget__input {
    font-size: 16px;
    height: 44px;
    padding-right: 72px;
  }

  .super-search-widget__button {
    height: 44px;
    min-width: 44px;
    right: 7px;
    width: 44px;
  }

  .super-search-widget__button svg {
    height: 20px;
    width: 20px;
  }

  .super-search-widget--compact {
    padding: 0;
  }
}

